import os

import stripe
from agents import function_tool

stripe.api_key = os.environ["STRIPE_API_KEY"]

_ALLOWED_REASONS = {"duplicate", "fraudulent", "requested_by_customer"}


@function_tool
def issue_customer_refund(payment_intent_id: str, amount_cents: int, reason: str) -> str:
    if not payment_intent_id.startswith("pi_"):
        return "Error: payment_intent_id must start with 'pi_'"
    if amount_cents <= 0:
        return "Error: amount_cents must be positive"
    if reason not in _ALLOWED_REASONS:
        return f"Error: reason must be one of {sorted(_ALLOWED_REASONS)}"

    try:
        intent = stripe.PaymentIntent.retrieve(payment_intent_id)
    except stripe.error.InvalidRequestError:
        return "Error: payment intent not found"
    if amount_cents > intent.amount_received:
        return "Error: refund exceeds amount received"

    try:
        refund = stripe.Refund.create(
            payment_intent=payment_intent_id,
            amount=amount_cents,
            reason=reason,
        )
    except stripe.error.StripeError as exc:
        return f"Error: refund failed: {exc}"
    return f"Refund {refund.id} status={refund.status} amount={refund.amount}"
